  save_batch_api_transactions_post: {
    parameters: {
      query?: never;
      header?: {
        /** @description The id of the scan page's build that sent it: a build older than the server takes is answered 409 build_too_old, before the batch is checked. Only the scan page sends it; a batch without it is checked as any other */
        "X-Inventory-Build"?: string | null;
      };
      path?: never;
      cookie?: never;
    };
    requestBody: {
      content: {
        "application/json": components["schemas"]["Batch"];
      };
    };
    responses: {
      /** @description Already written with this key */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["Saved"];
        };
      };
      /** @description Successful Response */
      201: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["Saved"];
        };
      };
      /** @description This device is not registered */
      403: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["DeviceRefusedReply"];
        };
      };
      /** @description The key was used for another batch (key_reused), or the page's build is too old for this server (build_too_old): keep the batch, and load the page again */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json":
            | components["schemas"]["KeyReusedReply"]
            | components["schemas"]["BuildTooOldReply"];
        };
      };
      /** @description Refused: each problem's kind (type) and where (loc), never in words, which the page makes from the kind. A body that cannot be a batch at all gets FastAPI's own 422 (BodyRefusedReply), with pydantic's types and words, a line's package size among them (SizeProblem) */
      422: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json":
            | components["schemas"]["BatchRefusedReply"]
            | components["schemas"]["BodyRefusedReply"];
        };
      };
      /** @description The database cannot answer; try again */
      503: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["UnavailableReply"];
        };
      };
    };
  };
